import random

def play_rock_paper_scissors():
    """
    Plays a game of Rock, Paper, Scissors against the user.
    """
    print("Let's play Rock, Paper, Scissors!")

    # Define the possible choices
    choices = ["rock", "paper", "scissors"]

    # Get the user's choice
    user_choice = input("Enter your choice (rock, paper, scissors): ").lower()

    # Ensure the user's choice is valid
    while user_choice not in choices:
        print("Invalid choice. Please enter 'rock', 'paper', or 'scissors'.")
        user_choice = input("Enter your choice (rock, paper, scissors): ").lower()

    # Generate a random choice for the computer
    computer_choice = random.choice(choices)

    # Determine the winner
    if user_choice == "rock":
        if computer_choice == "scissors":
            print(f"{computer_choice} covers {user_choice}! You win!")
        else:
            print(f"{user_choice} smashes {computer_choice}! I win!")
    elif user_choice == "paper":
        if computer_choice == "rock":
            print(f"{user_choice} covers {computer_choice}! You win!")
        else:
            print(f"{computer_choice} wraps {user_choice}! I win!")
    elif user_choice == "scissors":
        if computer_choice == "paper":
            print(f"{computer_choice} wraps {user_choice}! You win!")
        else:
            print(f"{user_choice} cuts {computer_choice}! I win!")
    else:
        print("Invalid choice. Please enter 'rock', 'paper', or 'scissors'.")

# Call the function
